(6503087, 966778, 64446, '<td valign="top">Right on!!!</td>', 'Right on!!!', '2011-08-12 22:35:11.000000', NULL, 1),
(6503101, 966342, 64446, '<td valign="top">Very creative and an excellent take on the challenge - outstanding image!</td>', 'Very creative and an excellent take on the challenge - outstanding image!', '2011-08-12 22:49:23.000000', NULL, 1),
(6503165, 965969, 64086, '<td valign="top">I love doing exactly what you did...turning photos the ''wrong way'' or flipping them upside down. Many times, it''s silly and just looks like a mistake, other times it can really bring a wonderful new extraordinary vision to something otherwise overlooked. I think you''ve done exactly that in this case. The composition, shapes and textures become much stronger when turned. My only minor criticism is that it feels a little too sharpened to me. Great job.</td>', 'I love doing exactly what you did...turning photos the ''wrong way'' or flipping them upside down. Many times, it''s silly and just looks like a mistake, other times it can really bring a wonderful new extraordinary vision to something otherwise overlooked. I think you''ve done exactly that in this case. The composition, shapes and textures become much stronger when turned. My only minor criticism is that it feels a little too sharpened to me. Great job.', '2011-08-13 00:45:39.000000', NULL, 1),
(6503166, 966842, 64086, '<td valign="top">Nicely seen.</td>', 'Nicely seen.', '2011-08-13 00:47:27.000000', NULL, 1),
