(6508544, 966672, 100831, '<td valign="top">Nice - love the title and the picture! That blur is crazy!!</td>', 'Nice - love the title and the picture! That blur is crazy!!', '2011-08-18 20:51:11.000000', NULL, 1),
(6508546, 966442, 100831, '<td valign="top">beautiful balance ... all of it.</td>', 'beautiful balance ... all of it.', '2011-08-18 20:53:31.000000', NULL, 1),
(6508547, 966710, 100831, '<td valign="top">this works well for drama and for the topic. Nice job!</td>', 'this works well for drama and for the topic. Nice job!', '2011-08-18 20:54:01.000000', NULL, 1),
(6508548, 966834, 100831, '<td valign="top">I think this actually works better as a horizontal than it would a vertical but I love the shot. The depth and delights of summer. 7</td>', 'I think this actually works better as a horizontal than it would a vertical but I love the shot. The depth and delights of summer. 7', '2011-08-18 20:55:37.000000', NULL, 1),
(6508549, 966850, 100831, '<td valign="top">So far as I know, toile is a woven fabric. I''m guessing the bear wasn''t planned. This is excellent, any way it goes.</td>', 'So far as I know, toile is a woven fabric. I''m guessing the bear wasn''t planned. This is excellent, any way it goes.', '2011-08-18 20:58:28.000000', NULL, 1),
(6508550, 966815, 100831, '<td valign="top">Tes! For the tall view AND the conversion. Excellent!</td>', 'Tes! For the tall view AND the conversion. Excellent!', '2011-08-18 20:59:53.000000', NULL, 1),
(6508556, 966842, 11769, '<td valign="top">Almost abstract, the horizontal lines crack me up. :)</td>', 'Almost abstract, the horizontal lines crack me up. :)', '2011-08-18 21:08:49.000000', NULL, 1),
(6508560, 965571, 100831, '<td valign="top">... at least it''s trying to rise... You can''t fool me :)</td>', '... at least it''s trying to rise... You can''t fool me :)', '2011-08-18 21:15:39.000000', NULL, 1),
(6508563, 966342, 97225, '<td valign="top">I really like this. The tipping puts all attention on the skater because it abstracts the busy background.</td>', 'I really like this. The tipping puts all attention on the skater because it abstracts the busy background.', '2011-08-18 21:18:09.000000', NULL, 1),
(6508566, 966047, 97225, '<td valign="top">Beautifully composed image makes great use of the theme of this challenge. I love the pattern formed by the repeating arches and their clear reflections.</td>', 'Beautifully composed image makes great use of the theme of this challenge. I love the pattern formed by the repeating arches and their clear reflections.', '2011-08-18 21:20:15.000000', NULL, 1),
(6508567, 966831, 97225, '<td valign="top">A visual delight. I love the wildflowers in the corner.</td>', 'A visual delight. I love the wildflowers in the corner.', '2011-08-18 21:21:41.000000', NULL, 1),
(6508568, 966625, 97225, '<td valign="top">Excellent use of the challenge theme - plenty of impact.</td>', 'Excellent use of the challenge theme - plenty of impact.', '2011-08-18 21:23:01.000000', NULL, 1),
(6508570, 966710, 97225, '<td valign="top">Wonderful dramatic shot. I have a feeling that this will ribbon.</td>', 'Wonderful dramatic shot. I have a feeling that this will ribbon.', '2011-08-18 21:25:15.000000', NULL, 1),
(6508576, 965988, 97225, '<td valign="top">Beautiful shot (Margaret?). I love that you are above the fog like that.<br/>I feel that this is a horizontal shot with a vertical point of interest - that the shot itself needs to be horizontal - rather than being of a vertical subject. Never mind, it doesn''t matter that much to me because there are many ways to interpret this theme and I think my own entry relies on arbitrary presentation.</td>', 'Beautiful shot (Margaret?). I love that you are above the fog like that.I feel that this is a horizontal shot with a vertical point of interest - that the shot itself needs to be horizontal - rather than being of a vertical subject. Never mind, it doesn''t matter that much to me because there are many ways to interpret this theme and I think my own entry relies on arbitrary presentation.', '2011-08-18 21:33:50.000000', NULL, 1),
(6508579, 966763, 97225, '<td valign="top">This is cool. The importance of the textures almost turns it abstract, and I could appreciate it turned on its side just as much. Very nice.</td>', 'This is cool. The importance of the textures almost turns it abstract, and I could appreciate it turned on its side just as much. Very nice.', '2011-08-18 21:35:51.000000', NULL, 1),
