(6508592, 966769, 97225, '<td valign="top">Couldn''t decide if the subject is horizontal or vertical, so you hedged your bets and went diagonal? That''s one way to beat the odds, LOL. It''s succeeded in making me look for longer and the longer I look the more I like it.</td>', 'Couldn''t decide if the subject is horizontal or vertical, so you hedged your bets and went diagonal? That''s one way to beat the odds, LOL. It''s succeeded in making me look for longer and the longer I look the more I like it.', '2011-08-18 21:45:26.000000', NULL, 1),
(6508598, 966795, 97225, '<td valign="top">This is sort of nice, but I feel that the subject is vertical anyway, and the loss of lower legs spoils the image a bit. If they had been lost due to a  horizontal framing it might have been more justified.</td>', 'This is sort of nice, but I feel that the subject is vertical anyway, and the loss of lower legs spoils the image a bit. If they had been lost due to a  horizontal framing it might have been more justified.', '2011-08-18 21:50:08.000000', NULL, 1),
